CREATE TABLE IF NOT EXISTS categories (id SERIAL PRIMARY KEY, "name" VARCHAR(255) NULL);
CREATE TABLE IF NOT EXISTS tags (id SERIAL PRIMARY KEY, "name" VARCHAR(255) NULL);
CREATE TABLE IF NOT EXISTS pets (id SERIAL PRIMARY KEY, "name" VARCHAR(255) NOT NULL, category_id INT NULL, status VARCHAR(16) NULL, CONSTRAINT fk_pets_category_id__id FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE SET NULL ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS pet_photo_urls (pet_id INT NOT NULL, url VARCHAR(2048) NOT NULL, CONSTRAINT fk_pet_photo_urls_pet_id__id FOREIGN KEY (pet_id) REFERENCES pets(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS pet_tags (pet_id INT, tag_id INT, CONSTRAINT pk_pet_tags PRIMARY KEY (pet_id, tag_id), CONSTRAINT fk_pet_tags_pet_id__id FOREIGN KEY (pet_id) REFERENCES pets(id) ON DELETE CASCADE ON UPDATE RESTRICT, CONSTRAINT fk_pet_tags_tag_id__id FOREIGN KEY (tag_id) REFERENCES tags(id) ON DELETE CASCADE ON UPDATE RESTRICT);
CREATE TABLE IF NOT EXISTS orders (id SERIAL PRIMARY KEY, pet_id INT NULL, quantity INT NULL, ship_date VARCHAR(64) NULL, status VARCHAR(16) NULL, complete BOOLEAN NULL, CONSTRAINT fk_orders_pet_id__id FOREIGN KEY (pet_id) REFERENCES pets(id) ON DELETE SET NULL ON UPDATE RESTRICT);
CREATE SEQUENCE IF NOT EXISTS categories_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;
CREATE SEQUENCE IF NOT EXISTS tags_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;
CREATE SEQUENCE IF NOT EXISTS pets_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;
CREATE SEQUENCE IF NOT EXISTS orders_id_seq START WITH 1 MINVALUE 1 MAXVALUE 9223372036854775807;
